// ====================
// Repository Interface
// ====================

// The Repository service provides a Twirp interface for exposing dependency
// relationships and entities related to a given repository. Both requests and
// responses reference repositories by GitHub (Rails model) Repository IDs, not DG IDs.
//
// The full graph of dependencies rooted at a given Repository is called a "solar system"
// by the Semantic Code team, this API's primary consumer. A "solar system" is the complete
// name-resolution graph for a single repository, extended to include all the repository's
// dependencies. See also:
// - Scope graphs: https://pl.ewi.tudelft.nl/research/projects/scope-graphs/
// - Stack graphs: https://docs.rs/stack-graphs/0.1.0/stack_graphs/
// - Aleph PR where the term was introduced: https://github.com/github/aleph/pull/888
type Repository interface {
	// Given a GitHub repository (model) ID, returns an unordered list of
	// all the input repository's direct dependencies, also as GitHub repo IDs.
	// As of now, this RPC method only returns Pip-managed Python dependencies.
	// See also: https://github.com/github/dependency-graph-api/pull/1285
	GetDirectDependencies(context.Context, *GetDirectDependenciesRequest) (*GetDirectDependenciesResponse, error)
}

