// The RepositoryDependenciesAPI is used to get dependencies given a containing repository.
type RepositoryDependenciesAPI interface {
	// Gets dependencies for a repository using any/all of build-time and source-code analysis.
	GetDependenciesForRepository(context.Context, *GetDependenciesForRepositoryRequest) (*GetDependenciesForRepositoryResponse, error)

	// Returns true or false depending on if the given Repository has associated Manifests
	HasManifests(context.Context, *HasManifestsRequest) (*HasManifestsResponse, error)

	// Gets a list of repository IDs that contain at least one dependency matching the criteria in the request.
	RepositoriesContainingDependency(context.Context, *RepositoriesContainingDependencyRequest) (*RepositoriesContainingDependencyResponse, error)

	SearchDependenciesForRepository(context.Context, *SearchDependenciesForRepositoryRequest) (*SearchDependenciesForRepositoryResponse, error)
}

